using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Core;
using Sem.Web.Data;
using Sem.Web.Runtime;
int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
var file=Path.Combine(Path.GetTempPath(),"sem-appearance-"+Guid.NewGuid().ToString("N")+".db");var now=DateTimeOffset.Parse("2026-10-26T00:00:00Z");var identity=new IdentityOptions();
try{
 var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await SqliteStorageInitializer.InitializeAsync(db);db.Users.Add(new(){Id="synthetic-user",UserName="synthetic@example.invalid",Email="synthetic@example.invalid",DisplayName="合成管理者",Enabled=true,EmailConfirmed=true,SecurityStamp="stamp"});await db.SaveChangesAsync();await EventListFixture.Seed(db);
 ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false)=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(AuthenticationSession.SessionClaim,"session"),new Claim(ClaimTypes.Role,"ServiceAdmin")}.Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user")]:[]),"synthetic"));
 Task<AppearanceResult> Read(string? e=null,ClaimsPrincipal? who=null)=>AppearanceReader.ReadAsync(db,who??Who(),identity,e,now);
 void Frozen(byte[] before,byte[] wal){Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[]),"配色参照でDB／WAL不変");}
 var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];var r=await Read();Check(r.State=="ok"&&r.View!.ActorId=="synthetic-user"&&r.View.EventId is null,"本人だけの最小参照");Check(r.View!.Palette=="green"&&r.View.Mode=="system"&&r.View.Colors is null,"未選択は固定mock既定greenと端末モード");Frozen(before,wal);
 var site=new SiteThemePreference{Id=1,ThemeId="blue",Mode=2};db.SiteThemePreferences.Add(site);await db.SaveChangesAsync();Check((await Read()).View is{Palette:"blue",Mode:"dark",Colors:null},"サイトの配色と明るさを解決");
 var ev=new EventThemePreference{EventId="public",ThemeId="rose",Mode=null};db.EventThemePreferences.Add(ev);await db.SaveChangesAsync();var eventView=(await Read("public")).View!;Check(eventView.Palette=="green"&&eventView.Mode=="dark"&&eventView.Colors?.Accent=="#A14365","イベント色とサイトモードを独立継承");Check(eventView.EventId=="public","解決対象をDTOへ束縛");Check((await Read("hidden")).State=="not-found","古い管理claimで担当外非公開色を読めない");Check((await Read("missing")).State=="not-found","存在しないイベントはnot-found");
 var person=new UserThemePreference{UserId="synthetic-user",ThemeId=null,Mode=1};db.UserThemePreferences.Add(person);await db.SaveChangesAsync();Check((await Read("public")).View is{Mode:"light",Colors.Accent:"#A14365"},"個人モードだけを優先しイベント色は維持");person.ThemeId="purple";person.Mode=0;await db.SaveChangesAsync();Check((await Read("public")).View is{Palette:"purple",Mode:"system",Colors:null},"明示systemを下位darkで上書きしない");
 db.Users.Add(new(){Id="synthetic-member",UserName="member@example.invalid",Email="member@example.invalid",DisplayName="合成メンバー",SecurityStamp="other-stamp",Enabled=true,EmailConfirmed=true});await db.SaveChangesAsync();db.UserThemePreferences.Add(new(){UserId="synthetic-member",ThemeId="coral",Mode=2});await db.SaveChangesAsync();Check((await Read()).View is{Palette:"purple",Mode:"system"},"別人の個人設定を使わない");
 foreach(var id in new[]{"green","blue","purple","amber","rose","teal","slate","navy","coral","mono"}){person.ThemeId=id;await db.SaveChangesAsync();var v=(await Read()).View;Check(v is not null&&(new[]{"green","blue","purple","amber"}.Contains(id)?v.Colors is null&&v.Palette==id:v.Colors is not null),"保存済み10テーマを解決 "+id);}
 var edited=await db.ThemeCatalogEntries.SingleAsync(t=>t.Id=="blue");edited.Accent="#2468AC";person.ThemeId="blue";await db.SaveChangesAsync();Check((await Read()).View is{Palette:"blue",Colors.Accent:"#2468AC"},"編集された基本色を固定既定へ戻さない");edited.Accent="#285F91";await db.SaveChangesAsync();
 var theme=new ThemeCatalogEntry{Id="custom-synthetic",Name="PRIVATE_THEME_NAME",Accent="#2468AC",Background="#FAFBFC",Surface="#FFFFFF",Text="#123456",BuiltIn=false};db.ThemeCatalogEntries.Add(theme);person.ThemeId=theme.Id;await db.SaveChangesAsync();var custom=(await Read()).View!;Check(custom.Colors==new AppearanceColors("#2468AC","#FAFBFC","#FFFFFF","#123456"),"カスタム4色を正確に投影");var json=JsonSerializer.Serialize(custom);foreach(var secret in new[]{"PRIVATE_THEME_NAME","custom-synthetic","@example.invalid","SecurityStamp","RowVersion","ThemeId","Passkeys"})Check(!json.Contains(secret),"解決に不要な私的情報を含めない "+secret);
 before=File.ReadAllBytes(file);wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];await Read("public");Frozen(before,wal);
 // 下位の破損も隠さず拒否。実DBへ行わず合成DBで一時的に制約を外す。
 await db.Database.OpenConnectionAsync();await db.Database.ExecuteSqlRawAsync("PRAGMA ignore_check_constraints=ON;");var lower=await db.ThemeCatalogEntries.SingleAsync(t=>t.Id=="blue");lower.Accent="url(x)";await db.SaveChangesAsync();Check((await Read()).State=="invalid","個人色の影にある不正サイト色も拒否");lower.Accent="#123456\n";await db.SaveChangesAsync();Check((await Read()).State=="invalid","末尾改行を含む疑似hexも拒否");lower.Accent="#285F91";site.Mode=9;await db.SaveChangesAsync();Check((await Read()).State=="invalid","下位の不正modeを拒否");site.Mode=2;await db.SaveChangesAsync();await db.Database.ExecuteSqlRawAsync("PRAGMA ignore_check_constraints=OFF;");await db.Database.CloseConnectionAsync();
 Check((await Read(who:new(new ClaimsIdentity()))).State=="unauthorized","匿名拒否");Check((await Read(who:Who("old"))).State=="unauthorized","stamp不一致拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","重複本人claim拒否");var actor=await db.Users.SingleAsync(u=>u.Id=="synthetic-user");actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","無効化で個人色も拒否");actor.Enabled=true;actor.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","未確認本人拒否");actor.EmailConfirmed=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=now.ToString("O")});await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","session失効拒否");
 Console.WriteLine($"保存配色・独立継承・現在認可 {checks}検査: 成功（合成DBのみ）");
}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var p in new[]{file,file+"-wal",file+"-shm"})File.Delete(p);}
